from scipy.optimize import least_squares
y=dP_dt
def run(fn,npar,trials=40):
    best=None
    np.random.seed(1)
    for s in range(trials):
        p0=np.random.randn(npar)
        try: r=least_squares(lambda p: fn(p)-y,p0)
        except Exception: continue
        if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
    return best, np.sum(best.fun**2)/np.sum((y-y.mean())**2)
